{"content": "{
  "main_characters": [
    {
      "name": "沈戡",
      "role": "protagonist",
      "identity": "市局刑侦支队重案组副队长，天衡系统第三批试点绑定者（绑定18个月），31岁",
      "traits": ["冷静精准", "极度自律", "控制欲强（伪装成责任感）", "共情力正在衰退（系统代价）", "骨子里的理想主义者"],
      "overt_motivation": "在12小时内破解未婚妻的杀人动机，阻止犯罪，保住两个人",
      "covert_motivation": "证明系统不是万能的——他开始怀疑自己是否正在变成系统的工具人，害怕失去作为人的判断力",
      "secret_fear": "失去感受爱的能力。他已经注意到自己对许盈的感情在变淡，但不确定是系统的代价还是自己本来就是这种人",
      "misperception_of_other": "认为许盈是需要被保护的、感性的理想主义者，没有意识到她比自己更冷静、更决绝",
      "hidden_connection": "天衡系统的创始团队中有人是他父亲的旧交，他绑定系统并非完全随机——系统选择了他"
    },
    {
      "name": "许盈",
      "role": "deuteragonist",
      "identity": "市公安局法医中心主检法医师，病理学博士，29岁",
      "traits": ["外柔内刚", "逻辑严密如手术刀", "极端的大局观", "感情内敛但记住所有细节", "有暗处行事的胆量"],
      "overt_motivation": "阻止沈戡在23:00执行护送证人任务，不惜以杀害的方式使他丧失行动能力",
      "covert_motivation": "她不想让沈戡成为城市毁灭的执行人——保护的不只是城市，更是沈戡的灵魂和良知",
      "secret_fear": "如果沈戡知道真相后仍选择执行任务（因为系统命令），意味着系统已经彻底吞噬了他的人性——那她就彻底失去他了",
      "misperception_of_other": "认为沈戡已被系统侵蚀太深，不再信任人类的判断力，所以选择不告诉他而直接动手",
      "hidden_connection": "她的博士导师韩夙明正是制造病毒的人，发现真相的同时也发现了恩师的罪行"
    }
  ],
  "supporting_characters": [
    {
      "name": "韩夙明",
      "function": "反转点",
      "identity": "前疾控中心首席病毒学家，许盈的博士生导师，58岁",
      "description": "温和的学者形象背后是极端理想主义者。他研发的'清洗者'病毒原本是用于生物防御的课题，却在发现政府将削减公共卫生经费时走向极端——他认为只有一场'可控的瘟疫'才能唤醒社会对公共卫生的重视。证人周淮就是他设计的'移动触发器'。他是整条灾难链的起点，也是许盈内心最大的裂痕。"
    },
    {
      "name": "周淮",
      "function": "反转点",
      "identity": "韩夙明实验室前研究员，34岁，证人/零号感染者",
      "description": "表面是制药公司投毒案的关键证人，实际体内携带经过改良的狂犬病毒变种'清洗者'。病毒通过特定温度激活（离开冷链环境24小时后进入传播期）。他本人并不知道自己是'人肉载体'——他以为自己只是掌握了投毒证据的逃亡者。是全书最核心的'移动炸弹'。"
    },
    {
      "name": "陆峥",
      "function": "助力",
      "identity": "重案组技术组组长，沈戡的搭档，33岁",
      "description": "务实、技术流的刑警。不知道天衡系统的存在，但极度信任沈戡的直觉。在12小时调查中承担大量外围调查工作。代表'普通刑警的正义'——不需要系统也能做正确的判断，是沈戡人性部分的镜像。"
    },
    {
      "name": "方竹清",
      "function": "阻碍",
      "identity": "天衡系统项目组驻地督导员，40岁",
      "description": "系统的'人形化身'。冷静、理性到近乎无情。她的职责是确保绑定者执行系统预警，对沈戡的'犹豫'零容忍。代表'绝对理性'的极端——如果系统说证人必须被救，那证人就必须被救，其他一切都是可接受的代价。她在后半段会成为逼迫沈戡做出选择的关键压力。"
    },
    {
      "name": "程鹤年",
      "function": "反转点",
      "identity": "市疾控中心传染病科主任，47岁",
      "description": "韩夙明的旧同事，是唯一能在短时间内验证'清洗者'病毒存在的人。但他与韩夙明有过学术恩怨，且正在竞争国家级课题。他的'验证'既是拯救城市的关键，也可能因个人恩怨而延误——代表'人性弱点'对科学判断的干扰。"
    },
    {
      "name": "老赵（赵恪铭）",
      "function": "助力",
      "identity": "法医中心副主任，许盈的直属上级，52岁",
      "description": "老派法医，沉默寡言但眼光毒辣。是许盈的职业引路人。在故事后半段会成为唯一察觉许盈异常的人，但他选择了信任和掩护——因为他从法医证据中独立验证了许盈的判断。代表'老一辈经验主义'对'系统主义'的无声反抗。"
    }
  ],
  "relationship_dynamics": "核心关系是沈戡与许盈的'双向清醒博弈'——两人都是高智商、强逻辑的人，两人都深爱对方但表达方式截然不同（他用控制和保护，她用沉默和行动）。系统（天衡）作为第三方力量横亘在两人之间：沈戡被系统绑定，必须执行预警；许盈不受系统约束，但她的行为被系统标记为'犯罪'。方竹清是系统意志的化身，陆峥是人性直觉的化身，韩夙明是灾难的源头也是许盈的精神枷锁，程鹤年是验证真相的关键但可能因私心延误。所有角色围绕一个核心问题展开：当系统的绝对正义与人类的相对判断冲突时，谁才是对的？"
}
", "path": "characters.json"}

{"content": "{
  "act_one": {
    "description": "第一幕·发现（约3.6万字，12章）——建立天衡系统世界观，引入沈戡的日常，在最亲密的时刻发现未婚妻额头的倒计时，震惊→否认→被迫接受→开始秘密调查。时间线：11:00-15:00。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "第一章·红字",
        "core_event": "沈戡在便利店抓获一名预谋持刀伤人的男子（系统常规预警），回到办公室接到任务：今晚23:00护送投毒案关键证人周淮出安全屋，送往市检察院。",
        "emotional_tone": "冷静、日常、暗流涌动",
        "key_scenes": ["便利店抓捕展示系统运作机制", "接到护送任务的简报", "系统的规则说明（通过内心独白自然展开）"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "第二章·11:07",
